"use client";

import { useState, useRef, useEffect, useId, type DragEvent, type ChangeEvent } from "react";
import { ImagePlus, Camera, X, Loader2, CheckCircle2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { formatFileSize, validateFile, matchesAccept, type FileConstraints } from "@/lib/upload";
import type { UploadStatus } from "./file-upload";
import { Field } from "./field";
import { ImageCropModal } from "./image-crop-modal";

/** Preview frame shape. */
export type PhotoVariant = "square" | "avatar" | "cover";

interface PhotoUploadProps {
  id?: string;
  label?: string;
  hint?: string;
  error?: string;
  required?: boolean;
  disabled?: boolean;
  /** Frame shape: square thumbnail, circular avatar, or wide cover banner. */
  variant?: PhotoVariant;
  /** Accepted image types. Defaults to `image/*`. */
  accept?: string;
  /** Max size in bytes. */
  maxSize?: number;
  /** Selected image file (controlled), or `null`. */
  value?: File | null;
  /** Existing image URL to show when there is no freshly-selected file (e.g. a saved avatar). */
  previewUrl?: string;
  /** Called with a valid image, or `null` when removed. */
  onSelect?: (file: File | null) => void;
  /** Called when a file fails validation. */
  onError?: (message: string) => void;
  status?: UploadStatus;
  progress?: number;
  /**
   * Enable an optional crop step: after selecting a valid image, a cropper
   * opens and `onSelect` receives the cropped image. The crop is locked to the
   * variant's aspect by default (avatar/square = 1:1, cover = 3:1).
   */
  crop?: boolean;
  /** Override the crop aspect ratio (width / height). Defaults from `variant`. */
  cropAspect?: number;
  /** Minimum cropped width in source pixels (blocks tiny crops). */
  cropMinWidth?: number;
}

const FRAME: Record<PhotoVariant, string> = {
  square: "size-32 rounded-xl",
  avatar: "size-28 rounded-full",
  cover: "h-40 w-full rounded-xl",
};

const VARIANT_ASPECT: Record<PhotoVariant, number> = {
  square: 1,
  avatar: 1,
  cover: 3,
};

/**
 * PhotoUpload — image-only picker with a live thumbnail preview. Supports a
 * square, circular avatar, or wide cover frame; drag-and-drop and click; an
 * optional crop step; and an uploading overlay. Presentational: wire uploads
 * via `onSelect` + `status`.
 */
export function PhotoUpload({
  id,
  label,
  hint,
  error,
  required,
  disabled,
  variant = "square",
  accept = "image/*",
  maxSize,
  value,
  previewUrl,
  onSelect,
  onError,
  status = "idle",
  progress = 0,
  crop = false,
  cropAspect,
  cropMinWidth,
}: PhotoUploadProps) {
  const reactId = useId();
  const inputId = id ?? reactId;
  const messageId = `${inputId}-message`;
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragOver, setDragOver] = useState(false);
  const [internalError, setInternalError] = useState<string | null>(null);
  const [objectUrl, setObjectUrl] = useState<string | null>(null);
  const [cropSrc, setCropSrc] = useState<string | null>(null);

  const shownError = error ?? internalError ?? undefined;
  const constraints: FileConstraints = { accept, maxSize };
  const preview = objectUrl ?? (value ? null : previewUrl ?? null);
  const effectiveAspect = cropAspect ?? VARIANT_ASPECT[variant];

  useEffect(() => {
    if (value) {
      const url = URL.createObjectURL(value);
      setObjectUrl(url);
      return () => URL.revokeObjectURL(url);
    }
    setObjectUrl(null);
  }, [value]);

  const accept_file = (file: File) => {
    // Guard against non-images even if the OS dialog allowed them.
    if (!matchesAccept(file, accept)) {
      const msg = "That file isn’t an image — choose a PNG, JPG, or WEBP.";
      setInternalError(msg);
      onError?.(msg);
      return;
    }
    const message = validateFile(file, constraints);
    if (message) {
      setInternalError(message);
      onError?.(message);
      return;
    }
    setInternalError(null);
    if (crop) {
      // Open the cropper; the cropped file is committed on confirm.
      setCropSrc(URL.createObjectURL(file));
    } else {
      onSelect?.(file);
    }
  };

  const closeCrop = () => {
    if (cropSrc) URL.revokeObjectURL(cropSrc);
    setCropSrc(null);
  };

  const onCropConfirm = (file: File) => {
    onSelect?.(file);
    closeCrop();
  };

  const onInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) accept_file(file);
    e.target.value = "";
  };

  const onDrop = (e: DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (disabled) return;
    const file = e.dataTransfer.files?.[0];
    if (file) accept_file(file);
  };

  const openPicker = () => !disabled && status !== "uploading" && inputRef.current?.click();
  const uploading = status === "uploading";

  return (
    <Field label={label} hint={hint} error={shownError} required={required} htmlFor={inputId} messageId={messageId}>
      <input
        ref={inputRef}
        id={inputId}
        type="file"
        accept={accept}
        disabled={disabled}
        onChange={onInputChange}
        className="sr-only"
        aria-describedby={messageId}
      />

      <div className={cn("flex items-start gap-4", variant === "cover" && "flex-col")}>
        <div
          role="button"
          tabIndex={disabled ? -1 : 0}
          aria-label={label ? `Upload ${label}` : "Upload photo"}
          aria-disabled={disabled || undefined}
          onClick={openPicker}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              openPicker();
            }
          }}
          onDragOver={(e) => {
            e.preventDefault();
            if (!disabled && !uploading) setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={onDrop}
          className={cn(
            "group relative flex shrink-0 items-center justify-center overflow-hidden border border-dashed bg-bg-secondary transition-colors",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent",
            FRAME[variant],
            disabled ? "cursor-not-allowed opacity-60" : "cursor-pointer hover:border-border-hover",
            dragOver && !disabled && "border-accent bg-accent-light",
            shownError && "border-error",
            preview && "border-solid"
          )}
        >
          {preview ? (
            <>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={preview} alt="" className="size-full object-cover" />
              {!disabled && !uploading && (
                <div className="absolute inset-0 flex items-center justify-center bg-overlay opacity-0 transition-opacity group-hover:opacity-100">
                  <Camera size={20} className="text-on-dark" aria-hidden />
                </div>
              )}
            </>
          ) : (
            <div className="flex flex-col items-center gap-1 px-2 text-center">
              <ImagePlus size={22} className={cn(dragOver ? "text-accent" : "text-text-tertiary")} aria-hidden />
              {variant === "cover" && <span className="text-xs text-text-secondary">Click or drag an image</span>}
            </div>
          )}

          {uploading && (
            <div className="absolute inset-0 flex items-center justify-center bg-overlay" aria-live="polite">
              <Loader2 size={20} className="animate-spin text-on-dark" aria-hidden />
              <span className="sr-only">Uploading {Math.round(progress)}%</span>
            </div>
          )}
        </div>

        <div className="min-w-0 space-y-1.5 pt-1">
          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              onClick={openPicker}
              disabled={disabled || uploading}
              className="rounded-lg border border-border bg-surface px-3 py-1.5 text-sm font-medium text-text transition-colors hover:bg-bg-hover disabled:cursor-not-allowed disabled:opacity-60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
            >
              {preview ? "Replace" : "Upload"}
            </button>
            {preview && !disabled && !uploading && (
              <button
                type="button"
                onClick={() => {
                  setInternalError(null);
                  onSelect?.(null);
                }}
                className="inline-flex items-center gap-1 rounded-lg px-2.5 py-1.5 text-sm text-text-secondary transition-colors hover:bg-bg-hover hover:text-error focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
              >
                <X size={14} aria-hidden />
                Remove
              </button>
            )}
          </div>
          <p className="text-xs text-text-tertiary">
            {accept === "image/*" ? "PNG, JPG, GIF, WEBP" : accept}
            {maxSize ? ` · up to ${formatFileSize(maxSize)}` : ""}
          </p>
          {value && <p className="truncate text-xs text-text-secondary">{value.name}</p>}
          {preview && !uploading && !shownError && (
            <p className="flex items-center gap-1 text-xs font-medium text-accent">
              <CheckCircle2 size={13} aria-hidden />
              {status === "complete" ? "Uploaded" : value ? "Added" : "Current photo"}
            </p>
          )}
        </div>
      </div>

      {crop && cropSrc && (
        <ImageCropModal
          open
          imageSrc={cropSrc}
          aspect={effectiveAspect}
          circular={variant === "avatar"}
          minWidth={cropMinWidth}
          outputName={value?.name ?? "cropped.png"}
          onConfirm={onCropConfirm}
          onCancel={closeCrop}
        />
      )}
    </Field>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with clsx semantics + Tailwind conflict resolution.
 * Prefer this in all components.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

/**
 * Concatenate class names, filtering out falsy values.
 * @deprecated Prefer {@link cn} — it also resolves Tailwind class conflicts.
 */
export function cx(...args: (string | false | null | undefined)[]): string {
  return args.filter(Boolean).join(" ");
}

/**
 * Focus ring style helper.
 * @deprecated Focus rings are now handled globally via the
 * `:focus-visible` rule in `globals.css` and the `focus-visible:*`
 * utilities. This remains only for backwards compatibility.
 */
export function ring(color: string = "var(--color-accent)") {
  return { outlineColor: color };
}

import {
  FileText,
  FileSpreadsheet,
  FileImage,
  FileArchive,
  FileVideo,
  FileAudio,
  FileCode,
  File as FileIcon,
  type LucideIcon,
} from "lucide-react";

/**
 * Shared, framework-agnostic helpers for the upload components
 * (FileUpload, FileUploadMultiple, PhotoUpload) and DocumentsTable.
 * Pure functions — safe to call during render.
 */

/** Broad file kind used for preview + icon selection. */
export type FileKind = "image" | "document" | "spreadsheet" | "archive" | "video" | "audio" | "code" | "other";

/** Format a byte count as a human-readable size, e.g. `2.4 MB`. */
export function formatFileSize(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(units.length - 1, Math.floor(Math.log(bytes) / Math.log(1024)));
  const value = bytes / 1024 ** i;
  // No decimals for bytes; one decimal otherwise.
  return `${i === 0 ? value : value.toFixed(1)} ${units[i]}`;
}

/** Lowercased extension without the dot (e.g. `pdf`), or `""` when none. */
export function fileExtension(name: string): string {
  const dot = name.lastIndexOf(".");
  return dot > 0 ? name.slice(dot + 1).toLowerCase() : "";
}

const EXT_KIND: Record<string, FileKind> = {
  // documents
  pdf: "document", doc: "document", docx: "document", txt: "document", rtf: "document", md: "document",
  // spreadsheets
  xls: "spreadsheet", xlsx: "spreadsheet", csv: "spreadsheet",
  // images
  png: "image", jpg: "image", jpeg: "image", gif: "image", webp: "image", svg: "image", avif: "image", heic: "image",
  // archives
  zip: "archive", rar: "archive", "7z": "archive", tar: "archive", gz: "archive",
  // media
  mp4: "video", mov: "video", webm: "video", avi: "video", mkv: "video",
  mp3: "audio", wav: "audio", ogg: "audio", m4a: "audio",
  // code
  js: "code", ts: "code", tsx: "code", jsx: "code", json: "code", html: "code", css: "code",
};

/** Classify a file by MIME type first, falling back to its extension. */
export function fileKind(nameOrType: string, mime?: string): FileKind {
  if (mime) {
    if (mime.startsWith("image/")) return "image";
    if (mime.startsWith("video/")) return "video";
    if (mime.startsWith("audio/")) return "audio";
    if (mime === "application/pdf") return "document";
    if (mime.includes("spreadsheet") || mime.includes("excel") || mime === "text/csv") return "spreadsheet";
    if (mime.includes("zip") || mime.includes("compressed") || mime.includes("tar")) return "archive";
  }
  return EXT_KIND[fileExtension(nameOrType)] ?? "other";
}

const KIND_ICON: Record<FileKind, LucideIcon> = {
  image: FileImage,
  document: FileText,
  spreadsheet: FileSpreadsheet,
  archive: FileArchive,
  video: FileVideo,
  audio: FileAudio,
  code: FileCode,
  other: FileIcon,
};

/** The lucide icon that represents a file kind. */
export function fileIcon(kind: FileKind): LucideIcon {
  return KIND_ICON[kind];
}

export interface FileConstraints {
  /** Max size per file, in bytes. */
  maxSize?: number;
  /**
   * Accepted types, in the same syntax as the input `accept` attribute:
   * extensions (".pdf"), MIME types ("image/png"), or wildcards ("image/*").
   */
  accept?: string;
}

/**
 * Validate a file against constraints. Returns a human-readable error string
 * ("what + why"), or `null` when the file is acceptable.
 */
export function validateFile(file: File, constraints: FileConstraints = {}): string | null {
  const { maxSize, accept } = constraints;
  if (typeof maxSize === "number" && file.size > maxSize) {
    return `File is too large — max ${formatFileSize(maxSize)}.`;
  }
  if (accept && !matchesAccept(file, accept)) {
    return `File type not allowed — accepted: ${accept}.`;
  }
  return null;
}

/** Whether a file satisfies an `accept` list (extensions, MIME, wildcards). */
export function matchesAccept(file: File, accept: string): boolean {
  const patterns = accept.split(",").map((p) => p.trim().toLowerCase()).filter(Boolean);
  if (patterns.length === 0) return true;
  const type = file.type.toLowerCase();
  const ext = `.${fileExtension(file.name)}`;
  return patterns.some((p) => {
    if (p.startsWith(".")) return ext === p;
    if (p.endsWith("/*")) return type.startsWith(p.slice(0, -1)); // e.g. "image/"
    return type === p;
  });
}

"use client";

import { type ReactNode } from "react";
import { cn } from "@/lib/utils";

interface FieldCounter {
  text: string;
  warn?: boolean;
}

interface FieldProps {
  label?: string;
  hint?: string;
  error?: string;
  required?: boolean;
  htmlFor?: string;
  counter?: FieldCounter;

  messageId?: string;
  children: ReactNode;
}

export function Field({
  label,
  hint,
  error,
  required,
  htmlFor,
  counter,
  messageId,
  children,
}: FieldProps) {
  const message = error || hint;
  return (
    <div className="flex w-full flex-col gap-1.5">
      {label && (
        <label
          htmlFor={htmlFor}
          className="flex items-center gap-1 text-[13px] font-medium text-text"
        >
          {label}
          {required && (
            <span className="text-error" aria-hidden>
              *
            </span>
          )}
        </label>
      )}
      {children}
      <div className="flex items-start justify-between gap-3">
        <p
          id={messageId}
          className={cn("text-xs leading-snug", error ? "text-error" : "text-text-secondary")}
        >
          {message || "\u00A0"}
        </p>
        {counter && (
          <span
            className={cn(
              "shrink-0 text-xs tabular-nums",
              counter.warn ? "text-error" : "text-text-tertiary"
            )}
          >
            {counter.text}
          </span>
        )}
      </div>
    </div>
  );
}

export const controlBase = cn(
  "w-full rounded-lg border text-sm bg-surface text-text transition-colors",
  "placeholder:text-text-tertiary",
  "focus:outline-none focus-visible:outline-none focus-visible:border-accent",
  "disabled:cursor-not-allowed disabled:bg-bg-secondary disabled:opacity-60",
  "read-only:bg-bg-secondary"
);

export function controlClasses(error?: string, disabled?: boolean, readOnly?: boolean) {
  return cn(
    error ? "border-error focus-visible:border-error" : "border-border",
    readOnly && "read-only:bg-bg-secondary",
    disabled && "text-text-tertiary"
  );
}

"use client";

import { useRef, useState, useEffect, useCallback, type PointerEvent, type KeyboardEvent } from "react";
import { Check, AlertTriangle } from "lucide-react";
import { cn } from "@/lib/utils";
import { Dialog } from "./dialog";
import { Button } from "./button";

/** A crop rectangle in canvas pixels. */
interface CropBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface ImageCropModalProps {
  open: boolean;
  /** Object URL / URL of the image to crop. The caller owns revoking object URLs. */
  imageSrc: string;
  /**
   * Fixed aspect ratio (width / height) the crop is locked to — e.g. 1 for a
   * square/avatar, 16/9 for a cover. Omit for a free-form crop.
   */
  aspect?: number;
  /** Whether to preview the crop as a circle (avatars). Visual only. */
  circular?: boolean;
  /** Minimum exported width in source pixels; smaller crops are blocked. */
  minWidth?: number;
  /** Output MIME type. Defaults to image/png (lossless). */
  outputType?: string;
  /** Output file name. Defaults to "cropped.png". */
  outputName?: string;
  /** Called with the cropped image as a File when the user confirms. */
  onConfirm: (file: File) => void;
  onCancel: () => void;
}

const CANVAS_MAX_W = 560;
const HANDLE = 14; // px — Fitts's Law: a comfortably large grab target
const MIN_BOX = 48; // px on canvas
const KEY_STEP = 4; // px per arrow press (×5 with Shift)

/**
 * ImageCropModal — an accessible, aspect-aware image cropper. Drag inside the
 * box to reposition, drag the handle (or use the keyboard) to resize; the crop
 * can be locked to an aspect ratio and previewed as a circle. Confirms with the
 * cropped image as a File.
 *
 * Accessibility & UX (grounded in the Mathesis UX books):
 * - Pointer Events unify mouse + touch; the box is keyboard-operable
 *   (arrows move, Shift+arrows resize) so it isn't gesture-only (Fitts's Law,
 *   mobile-patterns).
 * - The resize handle is a large, visible target (Fitts's Law).
 * - Validity + dimensions are announced via an aria-live region with an icon +
 *   text, never color alone (color-perception / accessibility).
 * - Only essential controls are shown (progressive disclosure).
 */
export function ImageCropModal({
  open,
  imageSrc,
  aspect,
  circular,
  minWidth = 0,
  outputType = "image/png",
  outputName = "cropped.png",
  onConfirm,
  onCancel,
}: ImageCropModalProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const [crop, setCrop] = useState<CropBox>({ x: 0, y: 0, w: 0, h: 0 });
  const [scale, setScale] = useState(1); // source px per canvas px
  const [canvasSize, setCanvasSize] = useState({ w: 0, h: 0 });
  const drag = useRef<{ mode: "move" | "resize"; px: number; py: number; box: CropBox } | null>(null);

  const outWidth = Math.round(crop.w * scale);
  const outHeight = Math.round(crop.h * scale);
  const tooSmall = minWidth > 0 && outWidth < minWidth;

  // Clamp a box to canvas bounds while (optionally) preserving aspect.
  const clampBox = useCallback(
    (box: CropBox, cw: number, ch: number): CropBox => {
      let { x, y, w, h } = box;
      w = Math.max(MIN_BOX, w);
      h = aspect ? w / aspect : Math.max(MIN_BOX, h);
      if (w > cw) { w = cw; h = aspect ? w / aspect : h; }
      if (h > ch) { h = ch; w = aspect ? h * aspect : w; }
      x = Math.max(0, Math.min(x, cw - w));
      y = Math.max(0, Math.min(y, ch - h));
      return { x, y, w, h };
    },
    [aspect]
  );

  // Load image + set initial centered crop.
  useEffect(() => {
    if (!open || !imageSrc) return;
    const img = new window.Image();
    img.onload = () => {
      imgRef.current = img;
      const cw = Math.min(img.naturalWidth, CANVAS_MAX_W);
      const s = img.naturalWidth / cw;
      const ch = Math.round(img.naturalHeight / s);
      setScale(s);
      setCanvasSize({ w: cw, h: ch });
      // Largest aspect-correct box that fits, centered.
      let w = cw;
      let h = aspect ? w / aspect : Math.round(ch * 0.8);
      if (h > ch) { h = ch; w = aspect ? h * aspect : w; }
      setCrop({ x: Math.round((cw - w) / 2), y: Math.round((ch - h) / 2), w, h });
    };
    img.src = imageSrc;
  }, [open, imageSrc, aspect]);

  // Draw the canvas: image, dim overlay, crop border/mask, grid, handle.
  useEffect(() => {
    const canvas = canvasRef.current;
    const img = imgRef.current;
    if (!canvas || !img || crop.w === 0) return;
    const { w: cw, h: ch } = canvasSize;
    canvas.width = cw;
    canvas.height = ch;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.clearRect(0, 0, cw, ch);
    ctx.drawImage(img, 0, 0, cw, ch);

    // Dim outside the crop.
    ctx.fillStyle = "rgba(0,0,0,0.55)";
    ctx.fillRect(0, 0, cw, crop.y);
    ctx.fillRect(0, crop.y + crop.h, cw, ch - crop.y - crop.h);
    ctx.fillRect(0, crop.y, crop.x, crop.h);
    ctx.fillRect(crop.x + crop.w, crop.y, cw - crop.x - crop.w, crop.h);

    // Circular mask preview: clear a circle within the box.
    if (circular) {
      ctx.save();
      ctx.beginPath();
      const r = Math.min(crop.w, crop.h) / 2;
      ctx.arc(crop.x + crop.w / 2, crop.y + crop.h / 2, r, 0, Math.PI * 2);
      ctx.strokeStyle = "rgba(255,255,255,0.9)";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.restore();
    }

    // Crop border.
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 2;
    ctx.strokeRect(crop.x + 1, crop.y + 1, crop.w - 2, crop.h - 2);

    // Rule-of-thirds grid.
    ctx.strokeStyle = "rgba(255,255,255,0.35)";
    ctx.lineWidth = 1;
    for (let i = 1; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(crop.x + (crop.w / 3) * i, crop.y);
      ctx.lineTo(crop.x + (crop.w / 3) * i, crop.y + crop.h);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(crop.x, crop.y + (crop.h / 3) * i);
      ctx.lineTo(crop.x + crop.w, crop.y + (crop.h / 3) * i);
      ctx.stroke();
    }

    // Resize handle (bottom-right), large for easy grabbing.
    ctx.fillStyle = "#fff";
    ctx.fillRect(crop.x + crop.w - HANDLE, crop.y + crop.h - HANDLE, HANDLE, HANDLE);
    ctx.strokeStyle = "rgba(0,0,0,0.25)";
    ctx.lineWidth = 1;
    ctx.strokeRect(crop.x + crop.w - HANDLE, crop.y + crop.h - HANDLE, HANDLE, HANDLE);
  }, [crop, canvasSize, circular]);

  const toCanvas = (e: PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current!;
    const rect = canvas.getBoundingClientRect();
    return {
      x: ((e.clientX - rect.left) / rect.width) * canvas.width,
      y: ((e.clientY - rect.top) / rect.height) * canvas.height,
    };
  };

  const onPointerDown = (e: PointerEvent<HTMLCanvasElement>) => {
    const p = toCanvas(e);
    const onHandle =
      p.x >= crop.x + crop.w - HANDLE - 4 &&
      p.x <= crop.x + crop.w + 4 &&
      p.y >= crop.y + crop.h - HANDLE - 4 &&
      p.y <= crop.y + crop.h + 4;
    const inside = p.x >= crop.x && p.x <= crop.x + crop.w && p.y >= crop.y && p.y <= crop.y + crop.h;
    if (!onHandle && !inside) return;
    canvasRef.current?.setPointerCapture(e.pointerId);
    drag.current = { mode: onHandle ? "resize" : "move", px: p.x, py: p.y, box: crop };
  };

  const onPointerMove = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!drag.current) return;
    const p = toCanvas(e);
    const { mode, px, py, box } = drag.current;
    const { w: cw, h: ch } = canvasSize;
    if (mode === "resize") {
      const nextW = box.w + (p.x - px);
      setCrop(clampBox({ ...box, w: nextW, h: aspect ? nextW / aspect : box.h + (p.y - py) }, cw, ch));
    } else {
      setCrop(clampBox({ ...box, x: box.x + (p.x - px), y: box.y + (p.y - py) }, cw, ch));
    }
  };

  const endDrag = (e: PointerEvent<HTMLCanvasElement>) => {
    drag.current = null;
    canvasRef.current?.releasePointerCapture?.(e.pointerId);
  };

  const onKeyDown = (e: KeyboardEvent<HTMLCanvasElement>) => {
    const { w: cw, h: ch } = canvasSize;
    const step = e.shiftKey ? KEY_STEP * 5 : KEY_STEP;
    const resize = e.altKey; // Alt+arrows resize, arrows move
    let next: CropBox | null = null;
    if (e.key === "ArrowLeft") next = resize ? { ...crop, w: crop.w - step } : { ...crop, x: crop.x - step };
    else if (e.key === "ArrowRight") next = resize ? { ...crop, w: crop.w + step } : { ...crop, x: crop.x + step };
    else if (e.key === "ArrowUp") next = resize ? { ...crop, w: crop.w - step } : { ...crop, y: crop.y - step };
    else if (e.key === "ArrowDown") next = resize ? { ...crop, w: crop.w + step } : { ...crop, y: crop.y + step };
    if (!next) return;
    e.preventDefault();
    if (resize && aspect) next.h = next.w / aspect;
    setCrop(clampBox(next, cw, ch));
  };

  const confirm = () => {
    const img = imgRef.current;
    if (!img || tooSmall) return;
    const sx = crop.x * scale;
    const sy = crop.y * scale;
    const sw = crop.w * scale;
    const sh = crop.h * scale;
    const out = document.createElement("canvas");
    out.width = Math.round(sw);
    out.height = Math.round(sh);
    const ctx = out.getContext("2d");
    if (!ctx) return;
    ctx.drawImage(img, sx, sy, sw, sh, 0, 0, out.width, out.height);
    out.toBlob(
      (blob) => {
        if (blob) onConfirm(new File([blob], outputName, { type: outputType }));
      },
      outputType,
      0.95
    );
  };

  return (
    <Dialog
      open={open}
      onClose={onCancel}
      size="lg"
      title="Crop image"
      description={
        aspect
          ? "Drag to reposition, drag the handle to resize. The crop keeps a fixed shape."
          : "Drag to reposition, drag the handle to resize."
      }
      footer={
        <>
          <Button variant="secondary" onClick={onCancel}>
            Cancel
          </Button>
          <Button onClick={confirm} disabled={tooSmall}>
            Use image
          </Button>
        </>
      }
    >
      <div className="space-y-3">
        <div className="flex items-center justify-center overflow-auto rounded-lg bg-surface-dark p-2" style={{ maxHeight: 420 }}>
          <canvas
            ref={canvasRef}
            tabIndex={0}
            role="slider"
            aria-label="Crop area — arrow keys move, Alt+arrows resize"
            aria-valuetext={`${outWidth} by ${outHeight} pixels`}
            className="max-w-full touch-none rounded outline-none focus-visible:ring-2 focus-visible:ring-accent"
            style={{ cursor: drag.current?.mode === "resize" ? "nwse-resize" : "grab" }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
            onKeyDown={onKeyDown}
          />
        </div>

        <p
          aria-live="polite"
          className={cn(
            "flex items-center gap-1.5 text-xs font-medium tabular-nums",
            tooSmall ? "text-error" : "text-text-secondary"
          )}
        >
          {tooSmall ? (
            <>
              <AlertTriangle size={13} aria-hidden />
              Crop is {outWidth}px wide — needs at least {minWidth}px.
            </>
          ) : (
            <>
              <Check size={13} className="text-accent" aria-hidden />
              {outWidth} × {outHeight} px
            </>
          )}
        </p>
      </div>
    </Dialog>
  );
}
